{
  "WorkOrder_Create": {
    "@type": "WorkOrder",
    "sourceSystem": "MVE",
    "id": "{{woIdJornada}}",
    "relatedParty": [
      {
        "@type": "CustomerValue",
        "category": "{{woCustomerCategory}}",
        "documentNumber": "{{woDocumentNumber}}",
        "id": "{{woCustomerId}}",
        "name": "{{woCustomerName}}",
        "contactMedium": [
          {
            "@type": "ContactMediumValue",
            "name": "{{woContactName}}",
            "characteristic": [
              {
                "@type": "ContactMediumValueCharacteristic",
                "emailAddress": "{{woEmailAddress}}",
                "mobileNumber": "{{woMobileNumber}}",
                "phoneNumber": "{{woPhoneNumber}}",
                "workNumber": "{{woWorkNumber}}"
              }
            ]
          }
        ]
      },
      {
        "@type": "CustomerOrderValue",
        "dateOfSale": "{{woDateOfSale}}",
        "id": "{{woOrderId}}",
        "orderProtocol": "{{woOrderProtocol}}",
        "characteristic": [
          {
            "@type": "Characteristic",
            "name": "Detail",
            "value": "{{woOrderDetail}}"
          }
        ]
      },
      {
        "@type": "WorkOrderPendency",
        "context": "TRIAGEM"
      }
    ],
    "workOrderItem": [
      {
        "@type": "WorkOrderItem",
        "id": "{{woIdJornada}}:1",
        "place": {
          "@type": "GeographicAddress",
          "cnl": "{{wfmCnl}}",
          "cnlAcronym": "{{woCnlAcronym}}",
          "city": "{{woCity}}",
          "neighborhood": "{{woNeighborhood}}",
          "postcode": "{{wfmPostcode}}",
          "stateOrProvince": "{{woStateOrProvince}}",
          "streetCode": "{{woStreetCode}}",
          "streetName": "{{woStreetName}}",
          "streetNr": "{{woStreetNr}}",
          "networkOwner": "{{wfmNetworkOwner}}",
          "accessTechnology": "{{wfmMediaType}}",
          "centralOffice": "{{wfmCentralOffice}}",
          "telephonicArea": "{{wfmTelephonicArea}}",
          "geographicLocation": {
            "@type": "GeographicLocation",
            "bbox": [
              "{{woLongitude}}",
              "{{woLatitude}}"
            ]
          },
          "geographicSite": {
            "@type": "Cabinet",
            "id": "{{wfmGeographicSiteId}}"
          },
          "geographicSubAddress": {
            "@type": "GeographicSubAddress",
            "name": "{{woComplement}}"
          }
        },
        "relatedEntity": [
          {
            "@type": "ProductEntity",
            "id": "{{woProductId}}",
            "name": "Banda Larga",
            "action": "Ativo",
            "status": "Ativo",
            "characteristic": [
              {
                "@type": "Characteristic",
                "name": "Designator",
                "value": "{{designador}}"
              },
              {
                "@type": "Characteristic",
                "name": "Technology",
                "value": "{{wfmMediaType}}"
              }
            ]
          }
        ],
        "specification": {
          "acronym": "TT_B",
          "type": "TROUBLETICKET",
          "specificationDescription": [
            {
              "name": "PRODUTO",
              "value": "Banda"
            },
            {
              "name": "TIPO",
              "value": "Defeito"
            },
            {
              "name": "DETALHE",
              "value": "{{woDetail}}"
            },
            {
              "name": "SEQUENCIA",
              "value": "1/1"
            }
          ]
        }
      }
    ]
  },
  "Appointment_Create": {
    "description": "Agendamento da atividade",
    "category": "CORPORATE",
    "canBeAntecipated": {{avisarHorarioMaisCedo}},
    "externalId": "{{woIdJornada}}:1",
    "scheduleDate": "{{slotScheduleDate}}",
    "relatedParty": [
      {
        "@type": "Attendant",
        "id": "{{wfmAttendantId}}",
        "role": ""
      },
      {
        "@type": "TimeSlot",
        "id": "{{slotTimeslot}}",
        "resourceId": "{{slotResourceId}}",
        "resourceName": "{{slotResourceName}}",
        "validFor": {
          "startDateTime": "{{slotInicio}}",
          "endDateTime": "{{slotFim}}"
        }
      }
    ],
    "note": [
      {
        "id": "CRM_NOTES",
        "text": "Agendamento realizado pelo cliente na jornada Fenix - Abertura de BD (VE)"
      },
      {
        "id": "ADDRESS_REFERENCE",
        "text": "{{woAddressReference}}"
      }
    ]
  }
}

{
  "@type": "ServiceProblemCase",
  "ticketType": "Case",
  "description": "Abertura de BD pelo VE (FTAT-933): diagnóstico automático não resolveu o problema",
  "severity": "3",
  "name": "Queda de Conexão",
  "requestedResolutionDate": "{{slotInicio}}",
  "expectedResolutionDate": "{{slotFim}}",
  "channel": {
    "name": "Alert"
  },
  "relatedEntity": [
    {
      "@type": "Service",
      "entity": {
        "@type": "ServiceTest",
        "name": "testSpecification",
        "id": "{{hpsdTestSpecificationId}}"
      }
    },
    {
      "@type": "Service",
      "entity": {
        "@type": "Service",
        "name": "mode",
        "id": "Proactive"
      }
    }
  ],
  "relatedParty": [],
  "troubleTicketCharacteristic": [
    {
      "name": "designadorAcesso",
      "value": "{{designador}}"
    },
    {
      "name": "WorkOrder",
      "value": "{{woNumero}}"
    },
    {
      "name": "previsaoAtendimento",
      "value": "{{slotData}} {{slotTimeslot}}"
    },
    {
      "name": "etapa",
      "value": "TRIAGEM"
    }
  ]
}
